def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def step_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_list(v):
        return v if isinstance(v, list) else []

    env = observation.get("environment_name", "")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = corners[0]
        best = -1
        for c in corners:
            d = manhattan((ox, oy), c)
            if d > best:
                best = d
                target = c
        return step_toward((sx, sy), target)

    if env == "territory_control":
        targets = safe_list(observation.get("unclaimed_cells")) or safe_list(observation.get("opponent_territory"))
        if not targets:
            targets = safe_list(observation.get("frontier_cells")) or safe_list(observation.get("neutral_cells"))
        if targets:
            best = targets[0]
            best_score = None
            for item in targets:
                p = pos(item, None)
                if p is None:
                    continue
                score = manhattan((sx, sy), p)
                if best_score is None or score < best_score:
                    best_score = score
                    best = p
            return step_toward((sx, sy), best)
        return step_toward((sx, sy), (ox, oy))

    resources = safe_list(observation.get("resources"))
    if not resources:
        resources = safe_list(observation.get("resource_positions")) or safe_list(observation.get("resource_cells"))
    if resources:
        best = None
        best_score = None
        for item in resources:
            p = pos(item, None)
            if p is None:
                continue
            score = manhattan((sx, sy), p)
            if best_score is None or score < best_score:
                best_score = score
                best = p
        if best is not None:
            return step_toward((sx, sy), best)

    if ox != sx or oy != sy:
        if abs(ox - sx) + abs(oy - sy) <= 2:
            if w and h:
                corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
                target = corners[0]
                best = -1
                for c in corners:
                    d = manhattan((ox, oy), c)
                    if d > best:
                        best = d
                        target = c
                return step_toward((sx, sy), target)
        return step_toward((sx, sy), (ox, oy))

    return [0, 0]

